package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class KeyedObjects2D_removeObject_TriageGen1Test {

    private KeyedObjects2D dataset;
    private final Comparable rowKey1 = "Row1";
    private final Comparable rowKey2 = "Row2";
    private final Comparable colKey1 = "Col1";
    private final Comparable colKey2 = "Col2";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test
    public void testRemoveObject_RowStillHasOtherObjects() {
        // Setup: Row1 has two objects (Col1 and Col2)
        dataset.addObject("Obj1", rowKey1, colKey1);
        dataset.addObject("Obj2", rowKey1, colKey2);

        // Action: Remove only one object from Row1
        dataset.removeObject(rowKey1, colKey1);

        // Assert: Row1 should still exist and contain Obj2
        assertEquals("Obj2", dataset.getObject(rowKey1, colKey2));
        assertEquals(1, dataset.getRowCount());
        // Check that the row key is still present in the list
        assertEquals(true, dataset.getRowKeys().contains(rowKey1));
    }






}

