public class KeyedObjects2D_removeObject_TriageGen1Test {

    private KeyedObjects2D dataset;
    private final Comparable rowKey1 = "Row1";
    private final Comparable rowKey2 = "Row2";
    private final Comparable colKey1 = "Col1";
    private final Comparable colKey2 = "Col2";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }





    @Test
    public void testRemoveObject_RowHasNullEntriesButNotEmpty() {
        // Setup: Row1 has an object and a null entry (simulating manual setObject(null...))
        dataset.addObject("Obj1", rowKey1, colKey1);
        dataset.setObject(null, rowKey1, colKey2);

        assertEquals(1, dataset.getRowCount());

        // Action: Remove the object, leaving only the null entry
        dataset.removeObject(rowKey1, colKey1);

        // Assert: Since all remaining items in the row are null, the row should be removed
        assertEquals(0, dataset.getRowCount());
        assertEquals(false, dataset.getRowKeys().contains(rowKey1));
    }


