    private final Comparable rowKey2 = "Row2";
    private final Comparable colKey1 = "Col1";
    private final Comparable colKey2 = "Col2";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }







    @Test
    public void testRemoveObject_NonExistentKeys() {
        // Setup: Empty dataset
        // Action: Attempt to remove from non-existent keys
        // Note: Depending on implementation of getRowIndex, this might throw exception.
        // Given the provided code, we assume the keys must exist or handle gracefully.

        dataset.addObject("Data", rowKey1, colKey1);

        // Remove a non-existent column from an existing row
        // This tests the branch where the loop runs but no non-null is found or found.
        dataset.removeObject(rowKey1, "NonExistentCol");

        // Since Col1 is still there, Row1 should remain
        assertEquals("Data", dataset.getObject(rowKey1, colKey1));
        assertEquals(1, dataset.getRowCount());
    }
